import{_ as i,l as n,o as e,c as d,v as t,p as s,x as o,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"未定义行为与优化","description":"","frontmatter":{"title":"未定义行为与优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/undefined-behavior-opt.md","filePath":"cs/undefined-behavior-opt.md","lastUpdated":1789023840000}'),h={name:"cs/undefined-behavior-opt.md"};function B(u,a,f,m,_,E){const r=n("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="未定义行为与优化" tabindex="-1">未定义行为与优化 <a class="header-anchor" href="#未定义行为与优化" aria-label="Permalink to &quot;未定义行为与优化&quot;">​</a></h1><div class="epigraph"><p>语言把某些状态标成未定义，优化器可假设它们不发生。于是「程序员觉得会做什么」与「生成代码做什么」在 UB 处分裂。</p><footer>—— 据 ISO C/C++ 未定义行为条款；Lattner, What Every C Programmer Should Know About Undefined Behavior；CompCert 对定义行为子集的对照整理</footer></div><p>上一课<a href="/cs/lto">LTO</a>让分析看见更多路径。缺口是<strong>合法变换的上限</strong>：有符号溢出、野指针、数据竞争（C）是 UB，优化可删检查、把循环当无限、根据「不能越界」收紧范围。本课钉「假设不发生」如何变成变换，不把全部 UB 列表当百科。中端课序在此收紧契约。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/type-soundness">健全性</a> 相对「出错状态」才有意义。C 的出错是 UB，语义允许任何目标码。优化：<code>if (p) load p; load p</code> 第二次可提前，因空指针 UB。缺口是<strong>把标准当许可</strong>，不是区间格细节。</p><p>程序员用溢出当绕回，优化可删 <code>if (x+1&lt;x)</code>。这是误解契约，不是编译器随机坏。</p><h3 id="ub-不是未指定或实现定义" tabindex="-1">UB 不是未指定或实现定义 <a class="header-anchor" href="#ub-不是未指定或实现定义" aria-label="Permalink to &quot;UB 不是未指定或实现定义&quot;">​</a></h3><p>未指定：选一种；实现定义：必须文档。UB：无要求。不要三词混用。</p><p><span class="marginnote">ISO C 3.4.3。Lattner 的系列短文。Regehr 的博客与 cse473 课常见材料。CompCert 选可定义子集。本课不发明标准条款编号之外的「秘密 UB」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IR 带 <code>nsw</code>/<code>nuw</code>/<code>inbounds</code> 等毒标志，把源语言 UB 显式化。变换：利用毒值传播、立即 UB 则后继不可达。诊断：sanitize（ASan/UBSan）在另一配置关闭这些假设。</p>',11)),(e(),s(c,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20UB%5B%22%E8%AF%AD%E8%A8%80%20UB%22%5D%0A%20%20UB%20--%3E%20ASSUME%5B%22%E4%BC%98%E5%8C%96%E5%81%87%E8%AE%BE%E4%B8%8D%E5%8F%91%E7%94%9F%22%5D%0A%20%20ASSUME%20--%3E%20XFORM%5B%22%E6%BF%80%E8%BF%9B%E5%8F%98%E6%8D%A2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与值范围、LICM、别名（TBAA）都吃同一口粮。fast-math 是浮点侧的类似开关，下一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>毒值 vs 立即 UB：LLVM 区分 poison 与 UB，避免「一条毒指令核掉整个函数」过激。语言律师与 IR 律师要对齐。不要在安全语言 IR 里默许 C 的 <code>nsw</code>。</p><p>LTO 使跨函数的 UB 假设传播更远，bug 表面更离奇。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 sanitizer。后课默认：中端合法性 ⊂ 语言未定义之外的行为。下一课 fast-math：浮点契约的显式放松。</p><p>也不把 UB 当「可以生成病毒」的许可证来讲利用；本课只讲优化契约。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UB 让优化假设某些状态不可达。</li><li>源级「绕回」直觉与 C 有符号溢出冲突。</li><li>sanitizer 与 <code>-fwrapv</code> 等改变契约。</li><li>出处：ISO C/C++；Lattner；对照 Leroy CompCert 子集。</li></ul>',9))])}const U=i(h,[["render",B]]);export{A as __pageData,U as default};
